  const m=JSON.parse(fs.readFileSync('.state/sessions/history/'+t+'/meta.json'));
  console.log('TARGET='+t);
  console.log('AGENT='+m.agent);
  console.log('STATUS='+m.status);
} else { console.log('NONE'); }
"

